import sys

def find_leaf_nodes(preorder):
    n = len(preorder)
    if n == 0:
        return []
    if n == 1:
        return [preorder[0]]

    left_child = [-1] * n
    right_child = [-1] * n

    stack = []

    for i in range(n):
        val = preorder[i]

        if not stack:
            stack.append((val, i))
        else:
            parent_idx = -1
            while stack:
                top_val, top_idx = stack[-1]
                if val < top_val:
                    if left_child[top_idx] == -1:
                        left_child[top_idx] = i
                    parent_idx = top_idx
                    break
                else:
                    right_child[top_idx] = i
                    stack.pop()

            if parent_idx == -1 and stack:
                top_val, top_idx = stack[-1]
                right_child[top_idx] = i
                parent_idx = top_idx

            stack.append((val, i))

    leaf_nodes = []
    for i in range(n):
        if left_child[i] == -1 and right_child[i] == -1:
            leaf_nodes.append(preorder[i])

    return leaf_nodes

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    if n == 0:
        print(-1)
        return

    preorder = list(map(int, data[1:n+1]))
    leaf_nodes = find_leaf_nodes(preorder)

    if not leaf_nodes:
        print(-1)
    else:
        print(' '.join(map(str, leaf_nodes)))

if __name__ == "__main__":
    main()
